"""`content_fingerprint` sees what `fingerprint` deliberately cannot (plan T4.0). No Docker.

A class-scoped `seeded_tree` reseeds when the tree has drifted from what it seeded. The existing
`fingerprint` cannot answer that: it digests `(gramps_id, handle)` pairs, so it is byte-identical
after every field write this server has — `set_surname`, `set_gender`, `confirm_person`,
`update_blog_post`. A reset keyed on it would hand the next class a tree whose surnames somebody
else rewrote, and would do it silently.

The pair below is the whole point of this module, and it is written as a pair on purpose: an
assertion that the content digest moved is satisfied by a digest that moves on *everything*
(a timestamp, a read), and an assertion that identity held is satisfied by one that never moves.
Each is the other's control.

`FakeRest` subclasses the real oracle over a fake transport, so these tests exercise the shipped
`content_snapshot`/`content_fingerprint` rather than a second implementation that agrees with
them by construction.
"""

from __future__ import annotations

import copy
from typing import Any

import pytest
from harness.records import content_signature
from stubs.fake_tree import FakeRest, FakeTree


@pytest.fixture
def tree() -> FakeTree:
    return FakeTree()


@pytest.fixture
def rest(tree: FakeTree) -> FakeRest:
    return FakeRest(tree)


def both(rest: FakeRest) -> tuple[str, str]:
    """(identity, content) — always read together, because each is the other's control."""
    return rest.fingerprint(), rest.content_fingerprint()


# -- the pair ---------------------------------------------------------------------------


def test_a_surname_change_moves_content_and_leaves_identity_alone(
    rest: FakeRest, tree: FakeTree
) -> None:
    """`set_surname` is the shape: one field, same handle, same id, same counts."""
    identity_before, content_before = both(rest)

    tree.person("I0000")["primary_name"]["surname_list"] = [{"surname": "Hagenbucher"}]
    identity_after, content_after = both(rest)

    assert identity_after == identity_before
    assert content_after != content_before


def test_a_note_rewritten_in_place_moves_content(rest: FakeRest, tree: FakeTree) -> None:
    """`update_blog_post` rewrites a note's text and moves nothing else — no count, no handle,
    no id. Measured shape (plan §5): `note["text"]` is `{"string": …}`, not a string."""
    tree.namespaces["notes"]["N0000"] = {
        "handle": "h-N0000",
        "gramps_id": "N0000",
        "text": {"string": "the 1918 influenza", "tags": []},
        "tag_list": [],
    }
    identity_before, content_before = both(rest)

    tree.namespaces["notes"]["N0000"]["text"]["string"] = "the 1919 influenza"
    identity_after, content_after = both(rest)

    assert identity_after == identity_before
    assert content_after != content_before


def test_a_family_losing_an_event_ref_moves_content(rest: FakeRest, tree: FakeTree) -> None:
    """The whole-object family PUT (`gramps_client.py:933`) can drop `event_ref_list` on the
    round-trip. No count moves — the Event objects survive, only the family stops pointing at
    them — so this is invisible to counts *and* to identity, and it severs a marriage."""
    tree.namespaces["families"]["F0000"]["event_ref_list"] = [{"ref": "h-E0000"}]
    identity_before, content_before = both(rest)

    tree.namespaces["families"]["F0000"]["event_ref_list"] = []
    identity_after, content_after = both(rest)

    assert identity_after == identity_before
    assert content_after != content_before


def test_a_tag_rename_moves_content(rest: FakeRest, tree: FakeTree) -> None:
    """Tags are matched by name everywhere in this suite, so a renamed tag is a changed tree
    even though the handle every record points at is untouched."""
    tree.namespaces["tags"]["T0000"] = {"handle": "h-T0000", "gramps_id": "T0000", "name": "Blog"}
    identity_before, content_before = both(rest)

    tree.namespaces["tags"]["T0000"]["name"] = "Blogeintrag"
    identity_after, content_after = both(rest)

    assert identity_after == identity_before
    assert content_after != content_before


# -- and the directions that must still work ---------------------------------------------


def test_a_new_person_moves_both(rest: FakeRest, tree: FakeTree) -> None:
    """The content digest is not a *replacement* for the identity one: a reseed has to notice a
    creation as well, and a digest that only watched fields would sail past the additive import
    that doubles the tree."""
    identity_before, content_before = both(rest)

    tree.add_person("I0003", "Folkmar", "Bernwald")
    identity_after, content_after = both(rest)

    assert identity_after != identity_before
    assert content_after != content_before


def test_two_reads_of_an_untouched_tree_agree(rest: FakeRest) -> None:
    """Otherwise every class reseeds every time, which is the 14.6 s the class scope exists to
    avoid — and nobody would notice, because a reset that always fires is never wrong."""
    assert rest.content_fingerprint() == rest.content_fingerprint()


def test_the_digest_survives_a_reordered_listing(rest: FakeRest, tree: FakeTree) -> None:
    """The API does not promise an order, and a digest that depends on one would reseed on the
    server's whim."""
    before = rest.content_fingerprint()

    people = tree.namespaces["people"]
    tree.namespaces["people"] = dict(reversed(list(people.items())))

    assert rest.content_fingerprint() == before


def test_a_read_alone_moves_nothing(rest: FakeRest) -> None:
    """`content_snapshot` is six reads; if any of them wrote, the reseed would be self-inflicted."""
    before = copy.deepcopy(rest.content_snapshot())

    assert rest.content_snapshot() == before


# -- the guard against a silent empty signature -------------------------------------------


def test_an_unsigned_namespace_raises_rather_than_digesting_to_nothing() -> None:
    """Stage 2's `signature()` falls through to the person shape for anything it does not name,
    which is right there (no class-A check addresses a note's content) and would be a hole here:
    an events record digesting to `("", "", "", None, (), ())` is a signature that agrees with
    every possible drift."""
    with pytest.raises(KeyError):
        content_signature("events", {"gramps_id": "E0000"}, {})


def test_every_signed_namespace_is_actually_signed() -> None:
    """The list and the dispatch are two places; if they disagree the digest silently drops a
    namespace, and dropping one is exactly the failure this module exists to prevent."""
    from harness.records import SIGNED

    record: dict[str, Any] = {"gramps_id": "X0000", "name": "n"}
    for namespace in SIGNED:
        assert content_signature(namespace, record, {}) is not None
